#!/usr/bin/env node
/**
 * @fluent-i18n-toolkit v3
 *
 * S0 lint: the Vue translation map must match the source it is generated
 * from, and every key in it must be reachable at runtime.
 *
 * WHY THIS EXISTS
 * ---------------
 * The PHP map(s) listed in i18n.config.json are generated by i18n.node.js
 * from the literal $t() / $_n() / $_x() calls in the source, plus the reserved
 * words file, and the app translates by EXACT string match against that map.
 * Nothing at runtime tells you a string is missing: $t() returns the English
 * text, so the screen looks fine in English and ships untranslated everywhere
 * else. Without this gate the map is refreshed only at release time and
 * drifts a release behind the UI.
 *
 * Checks:
 *   1. Stale map: a fresh generation differs from the committed file.
 *      Fix: `npm run translate` (or pnpm).
 *   2. Undefined reserved key: a call like $t('Agent_Title_Help') whose key
 *      is not in the reserved words file. The raw key would show on screen.
 *   3. Template literal key: $t(`...${x}...`). The msgid frozen in the map is
 *      source code; the runtime string never matches it.
 *   4. Dynamic context: $_x('text', variable). The contextual key cannot be
 *      built, so the call silently degrades to a plain lookup.
 *   5. HTML entity in a key: Vue decodes `&quot;` in templates at build time,
 *      so the bundle looks up `"` while the map keeps `&quot;`.
 *   6. Unused reserved word: an entry in the reserved words file that no
 *      source file references. Reported as a note only: dynamic lookups
 *      ($t(ticket.status)) are kept alive this way on purpose.
 *   7. Placeholder without a translator note: a key with %s / %d / %1$s and
 *      no `translators:` comment at any call site. Translators cannot tell
 *      what the placeholder stands for, so they cannot inflect around it.
 *   8. Dash glitch: an em dash, en dash or figure dash in a key or a reserved
 *      text. UI copy uses a period, comma, colon or parentheses.
 *   9. Whitespace in a key: a key that starts or ends with whitespace, or
 *      holds a double space / tab / newline. These are concatenation
 *      fragments ("Wait until ") that a translator cannot reorder; spacing
 *      belongs in the template, the value in a placeholder.
 *
 * Usage:  node tests/lint/translation-map.js
 *         node tests/lint/translation-map.js --self-test   (proof-of-catch)
 * Exit:   0 clean, 1 violations found
 *
 * This file is a copy of the shared toolkit (fluent-plugins-skills/i18n-unify).
 * Fix bugs there and re-run the installer with --update so every plugin gets it.
 */
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..', '..');
const generator = require(path.join(root, 'i18n.node.js'));

const ENTITY_PATTERN = /&(?:quot|amp|lt|gt|#\d+|#x[0-9a-f]+|[a-z]+);/i;
// The placeholder forms the runtime helper's applyPlaceholders() fills.
const PLACEHOLDER_PATTERN = /%(?:\d+\$)?[sd]/;
// em dash, en dash, figure dash.
const DASH_PATTERN = /[—–‒]/;
const WHITESPACE_PATTERN = /^\s|\s$|\s{2}|[\t\n\r]/;

/**
 * Run every check against a generation result and return the violations.
 * `committed` maps an output file path to its current on-disk content (or
 * null when the file does not exist yet). Separated from main() so the
 * self-test can run it against fixtures.
 */
function collectViolations(result, committed) {
    const violations = [];
    const warnings = [];
    const rel = (file) => path.relative(result.config.root, file).split(path.sep).join('/');

    result.outputs.forEach((output) => {
        const current = committed[output.file];
        if (current === null || typeof current === 'undefined') {
            // The PHP callers load this class at runtime, so a missing map is a fatal, not a clean check.
            violations.push(`${rel(output.file)} is missing: run \`npm run translate\` and commit it`);
            return;
        }
        if (current === output.php) {
            return;
        }
        const committedKeys = readMapKeys(current);
        const freshKeys = new Set(output.targets.flatMap((target) => result.rowsByTarget[target.name].map((row) => row.key)));
        const added = [...freshKeys].filter((key) => !committedKeys.has(key));
        const removed = [...committedKeys].filter((key) => !freshKeys.has(key));
        const detail = [
            `${added.length} string(s) missing from the map, ${removed.length} stale`,
            ...added.slice(0, 10).map((key) => `  + ${show(key)}`),
            ...removed.slice(0, 10).map((key) => `  - ${show(key)}`)
        ];
        if (added.length === 0 && removed.length === 0) {
            detail.push('  (keys match; a translator comment, reserved text or header changed)');
        }
        violations.push(`${rel(output.file)} is stale: run \`npm run translate\`\n${detail.join('\n')}`);
    });

    result.undefinedReservedKeys.forEach((item) => {
        violations.push(`${item.file}:${item.line} reserved key "${item.key}" has no entry in the reserved words file`);
    });

    result.problems.forEach((problem) => {
        if (problem.type === 'template-literal') {
            violations.push(`${problem.file}:${problem.line} template literal passed to a translation helper: \`${problem.text}\`; use a plain string with %s placeholders`);
        } else if (problem.type === 'dynamic-context') {
            violations.push(`${problem.file}:${problem.line} $_x('${problem.text}', ...) needs a literal context string`);
        }
    });

    const seenEntity = new Set();
    result.entries.forEach((entry) => {
        if (ENTITY_PATTERN.test(entry.text) && !seenEntity.has(entry.text)) {
            seenEntity.add(entry.text);
            violations.push(`${entry.file}:${entry.line} key contains an HTML entity; write the real character: ${show(entry.text)}`);
        }
    });

    // 7. A placeholder key is only translatable with a note saying what fills
    // it. The generator keeps the first comment seen for a key, so one call
    // site carrying it is enough. Reserved entries cannot carry a comment in
    // JSON and are checked by hand when added.
    const firstSite = {};
    result.entries.forEach((entry) => {
        if (!firstSite[entry.text]) {
            firstSite[entry.text] = entry;
        }
    });
    const seenPlaceholder = new Set();
    result.rows.forEach((row) => {
        if (row.reserved || row.comment || !PLACEHOLDER_PATTERN.test(row.text) || seenPlaceholder.has(row.key)) {
            return;
        }
        seenPlaceholder.add(row.key);
        const site = firstSite[row.text] || {};
        violations.push(`${site.file}:${site.line} placeholder string has no \`translators:\` comment; add one on the line above the call: ${show(row.text)}`);
    });

    // 8. Dashes typed by an editor or an AI tool read as a glitch in UI copy
    // and get copied into every locale.
    const seenDash = new Set();
    result.rows.forEach((row) => {
        if (!DASH_PATTERN.test(row.text) || seenDash.has(row.key)) {
            return;
        }
        seenDash.add(row.key);
        const site = firstSite[row.text] || firstSite[row.key];
        const where = row.reserved && !site ? `reserved words "${row.key}"` : `${site.file}:${site.line}`;
        violations.push(`${where} em/en dash in UI text; rewrite with a period, comma, colon or parentheses: ${show(row.text)}`);
    });

    // 9. Leading/trailing/double whitespace marks a concatenation fragment.
    const seenWhitespace = new Set();
    result.entries.forEach((entry) => {
        if (!WHITESPACE_PATTERN.test(entry.text) || seenWhitespace.has(entry.text)) {
            return;
        }
        seenWhitespace.add(entry.text);
        violations.push(`${entry.file}:${entry.line} key has leading, trailing or double whitespace; it is a concatenation fragment, use one string with a %s placeholder: ${show(entry.text)}`);
    });

    // Reserved words no call references are expected: Pro screens may share
    // the map, and dynamic lookups ($t(ticket.status)) are kept this way.
    if (result.unreferencedReserved.length > 0) {
        const list = result.unreferencedReserved.slice(0, 3).map((key) => `"${key}"`).join(', ');
        warnings.push(`${result.unreferencedReserved.length} reserved words entries are not referenced by source (Pro-shared or dynamic lookups): ${list}${result.unreferencedReserved.length > 3 ? ', ...' : ''}`);
    }

    return { violations, warnings };
}

/**
 * Keys of a committed map: single-quoted plain entries plus the
 * double-quoted contextual entries.
 */
function readMapKeys(php) {
    const keys = new Set();
    const single = /^\s*'((?:[^'\\]|\\.)*)'\s*=>/gm;
    const double = /^\s*"((?:[^"\\]|\\.)*)"\s*=>/gm;
    let match;

    while ((match = single.exec(php)) !== null) {
        keys.add(match[1].replace(/\\(['\\])/g, '$1'));
    }
    while ((match = double.exec(php)) !== null) {
        keys.add(match[1]
            .replace(/\\x04/g, generator.CONTEXT_DELIMITER)
            .replace(/\\(["\\$])/g, '$1'));
    }

    return keys;
}

function show(key) {
    const printable = key.split(generator.CONTEXT_DELIMITER).join(' | ');

    return JSON.stringify(printable.length > 80 ? printable.slice(0, 77) + '...' : printable);
}

function readCommitted(outputs) {
    const committed = {};
    outputs.forEach((output) => {
        committed[output.file] = fs.existsSync(output.file) ? fs.readFileSync(output.file, 'utf8') : null;
    });

    return committed;
}

function main() {
    const result = generator.generate();
    const { violations, warnings } = collectViolations(result, readCommitted(result.outputs));

    warnings.forEach((warning) => console.log(`translation-map: note: ${warning}`));

    if (violations.length === 0) {
        console.log(`translation-map: clean (${result.rows.length} strings in ${result.outputs.length} file(s))`);
        return 0;
    }

    violations.forEach((violation) => console.log(`translation-map: ${violation}`));
    console.log(`translation-map: ${violations.length} violation(s)`);

    return 1;
}

/**
 * Proof-of-catch: the fixture under tests/lint/fixtures/translation-map/
 * carries one instance of every call-site defect, and the fixture map is
 * deliberately stale. Exit 0 only when each check still fires.
 */
function selfTest() {
    const fixtureDir = path.join(__dirname, 'fixtures', 'translation-map');
    const real = generator.loadConfig();
    const config = {
        root: fixtureDir,
        textDomain: real.textDomain,
        namespace: real.namespace,
        abspathGuard: false,
        helpers: generator.DEFAULT_HELPERS,
        reservedKeyPattern: new RegExp(generator.DEFAULT_RESERVED_KEY_PATTERN),
        extensions: ['.vue', '.js'],
        mergeMethods: {},
        targets: [{
            name: 'fixture',
            sourceDirs: [path.join(fixtureDir, 'src')],
            exclude: [],
            output: path.join(fixtureDir, 'TransStrings.php'),
            className: 'TransStrings',
            method: 'getStrings',
            reservedWordsFile: path.join(fixtureDir, 'reservedWords.json'),
            reservedFallback: true
        }]
    };
    const result = generator.generate({ config });
    const { violations } = collectViolations(result, readCommitted(result.outputs));

    const expected = [
        ['stale map', /is stale/],
        ['undefined reserved key', /reserved key "Missing_Reserved_Key"/],
        ['template literal', /template literal passed/],
        ['dynamic context', /needs a literal context string/],
        ['html entity', /HTML entity/],
        ['placeholder without translator note', /Bad\.vue:\d+ placeholder string has no `translators:` comment/],
        ['dash in a key', /Bad\.vue:\d+ em\/en dash in UI text/],
        ['dash in a reserved text', /reserved words "Dashed_Help" em\/en dash/],
        ['whitespace fragment', /leading, trailing or double whitespace/]
    ];
    const missed = expected.filter(([, pattern]) => !violations.some((v) => pattern.test(v)));

    // The fixture also proves the positive paths: a translator comment, a
    // reserved word, a plural pair and a contextual key must land in the PHP.
    const php = result.outputs[0].php;
    if (!/\/\* translators: %s is the item count \*\/\n\s*'%s items'/.test(php)) {
        missed.push(['translator comment carried into the map']);
    }
    if (!php.includes("'Long_Help_Text' => __('A long paragraph that lives in the reserved words file.'")) {
        missed.push(['reserved word expanded']);
    }
    if (!php.includes('"Ticket status\\x04Open" => _x(\'Open\', \'Ticket status\'')) {
        missed.push(['contextual key emitted']);
    }
    if (!php.includes("'%s ticket' =>") || !php.includes("'%s tickets' =>")) {
        missed.push(['both $_n forms emitted']);
    }
    if (php.includes('Example in a comment')) {
        missed.push(['call inside a comment ignored']);
    }
    // A map file that was never generated (or was deleted) must fail, not pass as "unchanged".
    const missingMap = collectViolations(result, { [result.outputs[0].file]: null }).violations;
    if (!missingMap.some((v) => /is missing: run/.test(v))) {
        missed.push(['missing map file']);
    }

    if (missed.length === 0) {
        console.log(`translation-map self-test: all ${expected.length + 6} checks fire on fixtures`);
        return 0;
    }

    missed.forEach(([name]) => console.log(`translation-map self-test FAILED: ${name} no longer detected`));
    console.log('--- violations seen ---');
    violations.forEach((v) => console.log(v));

    return 1;
}

process.exit(process.argv.includes('--self-test') ? selfTest() : main());
